/* ---------- procedural sprites ---------- */
function mkCanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c}
function makeWisp(seed){
  const n=160,c=mkCanvas(n,n),g=c.getContext('2d'),r=mulberry(seed);
  let x=n/2,y=n*.74,a=-PI/2+(r()-.5)*.6;
  for(let i=0;i<24;i++){
    const rad=n*(.09+r()*.11),al=.05+r()*.07,gr=g.createRadialGradient(x,y,0,x,y,rad);
    gr.addColorStop(0,'rgba(255,240,224,'+al+')');gr.addColorStop(.5,'rgba(255,238,220,'+al*.38+')');gr.addColorStop(1,'rgba(255,236,216,0)');
    g.fillStyle=gr;g.fillRect(0,0,n,n);
    a+=(r()-.5)*1.2;x=clamp(x+Math.cos(a)*n*.04,n*.3,n*.7);y=clamp(y+Math.sin(a)*n*.04,n*.28,n*.74);
  }
  return c;
}
const sprites=[11,23,37,51,68].map(makeWisp);
const grain=mkCanvas(128,128);
{
  const g=grain.getContext('2d'),im=g.createImageData(128,128),d=im.data;
  for(let i=0;i<d.length;i+=4){const v=rnd()*255|0;d[i]=d[i+1]=d[i+2]=v;d[i+3]=255}
  g.putImageData(im,0,0);
}
let grainPat=null;

/* ---------- cached backdrop (wall glow + table) ---------- */
let bg=null;
function sceneTf(c){c.setTransform(DPR*S,0,0,DPR*S,CX*DPR,CY*DPR)}
function buildBackdrop(){
  const r=mulberry(77);
  bg=mkCanvas(cv.width,cv.height);
  const g=bg.getContext('2d');
  g.fillStyle='#070504';g.fillRect(0,0,bg.width,bg.height);
  sceneTf(g);
  const vw=VR-VL,vh=VB-VT;
  // warm haze behind the bowl
  let gr=g.createRadialGradient(-40,-170,20,-40,-170,760);
  gr.addColorStop(0,'rgba(128,62,24,.42)');gr.addColorStop(.35,'rgba(84,36,14,.24)');gr.addColorStop(.7,'rgba(40,16,8,.1)');gr.addColorStop(1,'rgba(10,5,3,0)');
  g.fillStyle=gr;g.fillRect(VL,VT,vw,vh);
  // table: grain on its own layer, masked into a pool of light
  const tb=mkCanvas(bg.width,bg.height),tg=tb.getContext('2d');
  sceneTf(tg);
  gr=tg.createLinearGradient(0,-140,0,560);
  gr.addColorStop(0,'#2a170d');gr.addColorStop(.5,'#3d2314');gr.addColorStop(1,'#2b170c');
  tg.fillStyle=gr;tg.fillRect(VL,VT,vw,vh);
  tg.lineCap='round';
  for(let i=0;i<240;i++){
    const d=r(),y=-130+d*d*720+r()*30,x=VL-100+r()*(vw+100),len=120+r()*620,wob=(r()-.5)*10*(.3+d);
    tg.lineWidth=.5+d*1.8*r();
    tg.strokeStyle=r()<.55?'rgba(0,0,0,'+(.1+r()*.22)+')':'rgba(255,186,120,'+(.02+r()*.06)+')';
    tg.beginPath();tg.moveTo(x,y);tg.quadraticCurveTo(x+len*.5,y+wob,x+len,y+(r()-.5)*4);tg.stroke();
  }
  // plank seams
  for(let i=0;i<5;i++){const y=-70+i*i*34+i*30;tg.strokeStyle='rgba(0,0,0,.4)';tg.lineWidth=1+i*.5;tg.beginPath();tg.moveTo(VL,y);tg.lineTo(VR,y);tg.stroke();
    tg.strokeStyle='rgba(255,190,130,.05)';tg.beginPath();tg.moveTo(VL,y+1.5+i*.4);tg.lineTo(VR,y+1.5+i*.4);tg.stroke()}
  tg.globalCompositeOperation='destination-in';
  tg.translate(0,215);tg.scale(1,.44);
  gr=tg.createRadialGradient(0,0,120,0,0,820);
  gr.addColorStop(0,'rgba(0,0,0,.95)');gr.addColorStop(.4,'rgba(0,0,0,.55)');gr.addColorStop(.75,'rgba(0,0,0,.16)');gr.addColorStop(1,'rgba(0,0,0,0)');
  tg.fillStyle=gr;tg.fillRect(-4000,-4000,8000,8000);
  g.setTransform(1,0,0,1,0,0);g.drawImage(tb,0,0);
  grainPat=ctx.createPattern(grain,'repeat');
}

function resize(){
  DPR=Math.min(window.devicePixelRatio||1,2);
  W=Math.max(1,window.innerWidth);H=Math.max(1,window.innerHeight);
  cv.width=Math.round(W*DPR);cv.height=Math.round(H*DPR);
  S=Math.min(W/880,H/800);CX=W/2;CY=H*.5+100*S;
  VL=-CX/S;VT=-CY/S;VR=(W-CX)/S;VB=(H-CY)/S;
  buildBackdrop();
}

/* ---------- bowl ---------- */
function drawBowlBody(){
  let g;
  // cast shadow on the table, leaning away from the light
  ctx.save();ctx.translate(-LX*30,236);ctx.scale(1,.25);
  g=ctx.createRadialGradient(0,0,70,0,0,350);
  g.addColorStop(0,'rgba(0,0,0,.94)');g.addColorStop(.45,'rgba(0,0,0,.6)');g.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,350,0,TAU);ctx.fill();ctx.restore();
  // foot ring (unglazed clay)
  g=ctx.createLinearGradient(-100,0,100,0);
  g.addColorStop(0,'#0b0806');g.addColorStop(clamp(.5+LX*.3,.1,.9),'#3a2a20');g.addColorStop(1,'#0b0806');
  ctx.fillStyle=g;ctx.fill(footPath);
  // glazed body
  g=ctx.createLinearGradient(0,0,0,240);
  g.addColorStop(0,'#27404b');g.addColorStop(.3,'#1a2d37');g.addColorStop(.75,'#101c24');g.addColorStop(1,'#0a1218');
  ctx.fillStyle=g;ctx.fill(bodyPath);
  ctx.save();ctx.clip(bodyPath);
  const hl=clamp(.5+LX*.3,.14,.86);
  g=ctx.createLinearGradient(-300,0,300,0);
  g.addColorStop(0,'rgba(0,0,0,.82)');g.addColorStop(hl,'rgba(0,0,0,0)');g.addColorStop(1,'rgba(0,0,0,.82)');
  ctx.fillStyle=g;ctx.fillRect(-310,-160,620,420);
  // glaze bands
  ctx.lineWidth=2.4;ctx.strokeStyle='rgba(214,176,128,.26)';
  for(const h of [24,31]){const r=prof(h);ctx.beginPath();ctx.ellipse(0,CE*h,r,r*K,0,0,PI);ctx.stroke()}
  ctx.lineWidth=7;ctx.strokeStyle='rgba(6,12,16,.4)';
  {const r=prof(150);ctx.beginPath();ctx.ellipse(0,CE*150,r,r*K,0,0,PI);ctx.stroke()}
  // kiln speckle
  for(const s of speck){ctx.fillStyle='rgba(190,222,232,'+s[3]+')';ctx.fillRect(s[0],s[1],s[2],s[2])}
  // soft specular streak
  ctx.globalCompositeOperation='screen';
  ctx.save();ctx.translate((hl-.5)*600,96);ctx.scale(.46,1);
  g=ctx.createRadialGradient(0,0,0,0,0,170);
  g.addColorStop(0,'rgba(170,205,215,.36)');g.addColorStop(.4,'rgba(120,160,175,.14)');g.addColorStop(1,'rgba(90,120,140,0)');
  ctx.fillStyle=g;ctx.fillRect(-400,-200,800,400);ctx.restore();
  // warm bounce from the table
  g=ctx.createLinearGradient(0,150,0,246);
  g.addColorStop(0,'rgba(200,96,40,0)');g.addColorStop(1,'rgba(200,96,40,.3)');
  ctx.fillStyle=g;ctx.fillRect(-310,150,620,100);
  ctx.globalCompositeOperation='source-over';
  ctx.restore();
}
function drawRim(){
  const hl=clamp(.5+LX*.4,.08,.92);
  let g=ctx.createLinearGradient(-300,0,300,0);
  g.addColorStop(0,'#3b2a1f');g.addColorStop(hl,'#d0a57a');g.addColorStop(1,'#35251b');
  ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,0,RX,RY,0,0,TAU);ctx.fill();
  // inner wall
  g=ctx.createLinearGradient(0,-140,0,150);
  g.addColorStop(0,'#2a424d');g.addColorStop(.35,'#16262f');g.addColorStop(1,'#080d11');
  ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,IY,IRX,IRY,0,0,TAU);ctx.fill();
  // glow of the broth on the back wall
  ctx.save();ctx.beginPath();ctx.ellipse(0,IY,IRX,IRY,0,0,TAU);ctx.clip();
  g=ctx.createLinearGradient(0,-140,0,-60);
  g.addColorStop(0,'rgba(255,150,60,0)');g.addColorStop(1,'rgba(255,150,60,.28)');
  ctx.fillStyle=g;ctx.fillRect(-300,-140,600,90);ctx.restore();
  // lip highlight facing the light
  const a=Math.atan2((light.y)*2,light.x);
  ctx.lineCap='round';
  ctx.strokeStyle='rgba(255,226,186,.22)';ctx.lineWidth=3;
  ctx.beginPath();ctx.ellipse(0,1,RX-5,RY-3,0,a-1.1,a+1.1);ctx.stroke();
  ctx.strokeStyle='rgba(255,240,214,.7)';ctx.lineWidth=1.4;
  ctx.beginPath();ctx.ellipse(0,1,RX-5,RY-3,0,a-.42,a+.42);ctx.stroke();
  ctx.strokeStyle='rgba(0,0,0,.45)';ctx.lineWidth=1.2;
  ctx.beginPath();ctx.ellipse(0,IY,IRX,IRY,0,0,TAU);ctx.stroke();
}

/* ---------- broth ---------- */
const oil=[];
for(let i=0;i<64;i++){
  const a=rnd()*TAU,d=.3+.66*Math.sqrt(rnd());
  oil.push({u:Math.cos(a)*d,v:Math.sin(a)*d,r:i<10?rr(9,17):rr(2.5,9),red:rnd()<.4,ph:rnd()*TAU,w:rr(.6,1.4)});
}
function stepOil(dt,t){
  for(const o of oil){
    const d=Math.hypot(o.u,o.v)||1e-3;
    // slow convection swirl + wander
    let du=-o.v*.022*o.w+noise(o.u*2+o.ph,t*.07)*.012,dv=o.u*.022*o.w+noise(o.v*2-o.ph,t*.07+9)*.012;
    for(const r of ripples){const age=t-r.born;if(age>2.4)continue;
      const ex=o.u-r.u,ey=o.v-r.v,ed=Math.hypot(ex,ey)||1e-3,x=ed-age*.5;
      const f=r.amp*(1-age/2.4)*Math.exp(-x*x*50)*.22;du+=ex/ed*f;dv+=ey/ed*f}
    if(d>.93){du-=o.u/d*(d-.93)*2;dv-=o.v/d*(d-.93)*2}
    if(d<.28){du+=o.u/d*.02;dv+=o.v/d*.02}
    o.u+=du*dt;o.v+=dv*dt;
  }
}
function drawBroth(t){
  let g;
  ctx.save();
  ctx.beginPath();ctx.ellipse(0,IY,IRX-1,IRY-1,0,0,TAU);ctx.clip();
  ctx.beginPath();ctx.ellipse(0,BY,BRX,BRY,0,0,TAU);ctx.clip();
  ctx.save();ctx.translate(0,BY);ctx.scale(1,K);
  g=ctx.createRadialGradient(-30+LX*50,-50,10,0,0,BRX);
  g.addColorStop(0,'#f3bd6c');g.addColorStop(.4,'#de943f');g.addColorStop(.78,'#b66a27');g.addColorStop(1,'#70370f');
  ctx.fillStyle=g;ctx.fillRect(-BRX,-BRX,2*BRX,2*BRX);
  // creamy sesame swirls drifting in the broth
  for(let i=0;i<7;i++){
    const a=i*2.4+t*.05*(i%2?1:-1.3),d=70+50*Math.sin(i*1.7+t*.11),x=Math.cos(a)*d*1.6,y=Math.sin(a)*d*1.5,r=90+30*Math.sin(i+t*.2);
    g=ctx.createRadialGradient(x,y,0,x,y,r);
    g.addColorStop(0,i%3?'rgba(255,228,176,.2)':'rgba(150,62,14,.2)');g.addColorStop(1,i%3?'rgba(255,228,176,0)':'rgba(150,62,14,0)');
    ctx.fillStyle=g;ctx.fillRect(x-r,y-r,2*r,2*r);
  }
  ctx.restore();
  drawNoodles(t);
  ctx.translate(0,BY);ctx.scale(1,K);
  // where the noodles sink back under
  g=ctx.createRadialGradient(0,10,BRX*.5,0,0,BRX);
  g.addColorStop(0,'rgba(196,112,40,0)');g.addColorStop(.55,'rgba(188,104,36,.55)');g.addColorStop(1,'rgba(140,72,22,.95)');
  ctx.fillStyle=g;ctx.fillRect(-BRX,-BRX,2*BRX,2*BRX);
  // oil pearls
  const pg=new Path2D(),pr=new Path2D(),ph=new Path2D();
  for(const o of oil){
    const x=o.u*BRX,y=o.v*BRX,r=o.r*(1+.05*Math.sin(t*1.3+o.ph));
    const p=o.red?pr:pg;p.moveTo(x+r,y);p.arc(x,y,r,0,TAU);
    const hx=x-r*.34+LX*r*.3,hy=y-r*.38,hr=r*.2+.5;ph.moveTo(hx+hr,hy);ph.arc(hx,hy,hr,0,TAU);
  }
  ctx.fillStyle='rgba(255,206,112,.2)';ctx.fill(pg);
  ctx.fillStyle='rgba(216,52,14,.55)';ctx.fill(pr);
  ctx.lineWidth=1.3;ctx.strokeStyle='rgba(255,226,160,.4)';ctx.stroke(pg);
  ctx.strokeStyle='rgba(255,150,80,.5)';ctx.stroke(pr);
  ctx.strokeStyle='rgba(70,24,0,.22)';ctx.save();ctx.translate(.8,1.6);ctx.stroke(pg);ctx.stroke(pr);ctx.restore();
  ctx.fillStyle='rgba(255,250,232,.62)';ctx.fill(ph);
  // ripples
  for(const r of ripples){
    const age=t-r.born;if(age>2.4||age<0)continue;
    const f=1-age/2.4,al=Math.min(1,r.amp*1.4)*f*f,x=r.u*BRX,y=r.v*BRX;
    for(let j=0;j<3;j++){
      const rad=(age*.5-j*.07)*BRX;if(rad<=2)continue;
      ctx.lineWidth=3.4-j*.8;ctx.strokeStyle='rgba(255,240,205,'+al*(.5-j*.13)+')';
      ctx.beginPath();ctx.arc(x,y,rad,0,TAU);ctx.stroke();
      ctx.strokeStyle='rgba(84,34,4,'+al*(.4-j*.1)+')';
      ctx.beginPath();ctx.arc(x,y,rad+5,0,TAU);ctx.stroke();
    }
  }
  // moving sheen of the light on the surface
  ctx.globalCompositeOperation='screen';
  const sx=LX*130-10,sy=-70+LY*120;
  for(let i=0;i<3;i++){
    const x=sx+Math.sin(t*.5+i*2.1)*26*i,y=sy+Math.cos(t*.4+i*1.3)*30*i,r=200-i*50;
    g=ctx.createRadialGradient(x,y,0,x,y,r);
    g.addColorStop(0,'rgba(255,236,196,'+(.3-i*.07)+')');g.addColorStop(1,'rgba(255,220,170,0)');
    ctx.fillStyle=g;ctx.fillRect(x-r,y-r,2*r,2*r);
  }
  ctx.globalCompositeOperation='source-over';
  // depth at the edge + shade thrown by the near wall
  g=ctx.createRadialGradient(0,0,BRX*.74,0,0,BRX);
  g.addColorStop(0,'rgba(46,16,0,0)');g.addColorStop(1,'rgba(46,16,0,.7)');
  ctx.fillStyle=g;ctx.fillRect(-BRX,-BRX,2*BRX,2*BRX);
  ctx.lineWidth=2;ctx.strokeStyle='rgba(255,214,150,.42)';
  ctx.beginPath();ctx.arc(0,0,BRX-1.5,PI*1.05,PI*1.95);ctx.stroke();
  ctx.restore();
}

/* ---------- noodles ---------- */
function catmull(p,s){
  const n=p.length-1,f=clamp(s,0,.9999)*n,i=Math.floor(f),t=f-i;
  const a=p[Math.max(0,i-1)],b=p[i],c=p[i+1],d=p[Math.min(n,i+2)],o=[0,0];
  for(let k=0;k<2;k++)o[k]=.5*((2*b[k])+(-a[k]+c[k])*t+(2*a[k]-5*b[k]+4*c[k]-d[k])*t*t+(-a[k]+3*b[k]-3*c[k]+d[k])*t*t*t);
  return o;
}
const skeins=[
  {p:[[-.2,-.56],[-.12,-.2],[.1,.12],[.06,.5],[-.2,.74]],n:8},
  {p:[[.78,.08],[.42,.2],[.05,0],[-.3,.1],[-.6,-.22]],n:7},
  {p:[[-.74,.2],[-.42,-.08],[-.05,.12],[.3,.42],[.64,.34]],n:9},
  {p:[[-.62,.54],[-.25,.3],[.12,.22],[.42,-.05],[.62,-.32]],n:8},
  {p:[[.3,.7],[.12,.42],[-.12,.3],[-.2,.02],[.02,-.2],[.3,-.3]],n:6}
];
const strands=[];
const NS=34;
for(const sk of skeins){
  for(let i=0;i<sk.n;i++){
    const base=new Float32Array(NS*4),off=(i-(sk.n-1)/2)*.031+rr(-.004,.004);
    for(let j=0;j<NS;j++){
      const s=j/(NS-1),a=catmull(sk.p,s),b=catmull(sk.p,s+.01),c=catmull(sk.p,Math.max(0,s-.01));
      let tx=b[0]-c[0],ty=b[1]-c[1];const tl=Math.hypot(tx,ty)||1;tx/=tl;ty/=tl;
      base[j*4]=a[0];base[j*4+1]=a[1];base[j*4+2]=-ty;base[j*4+3]=tx;
    }
    strands.push({base,off,f:rr(7,12),ph:rnd()*TAU,amp:rr(.006,.014),sp:rr(.35,.7),
      col:'hsl('+rr(42,48).toFixed(0)+','+rr(66,78).toFixed(0)+'%,'+rr(68,77).toFixed(0)+'%)',w:rr(6.2,7.4)});
  }
}
function drawNoodles(t){
  ctx.lineCap='round';ctx.lineJoin='round';
  for(const st of strands){
    const b=st.base,p=new Path2D();
    for(let j=0;j<NS;j++){
      const s=j/(NS-1),wv=st.off+st.amp*Math.sin(s*st.f+st.ph+t*st.sp)+.004*Math.sin(s*23+st.ph*3-t*.9);
      const u=b[j*4]+b[j*4+2]*wv,v=b[j*4+1]+b[j*4+3]*wv;
      const x=u*BRX,y=BY+v*BRY-mound(u,v)+rippleAt(u,v,t)*3;
      if(j)p.lineTo(x,y);else p.moveTo(x,y);
    }
    ctx.lineWidth=st.w+2.6;ctx.strokeStyle='rgba(112,56,10,.6)';ctx.stroke(p);
    ctx.lineWidth=st.w;ctx.strokeStyle=st.col;ctx.stroke(p);
    ctx.save();ctx.translate(-.7+LX*1.1,-1.5);
    ctx.lineWidth=1.9;ctx.strokeStyle='rgba(255,250,222,.6)';ctx.stroke(p);ctx.restore();
  }
}

/* ---------- toppings: data ---------- */
const scallions=[],sesame=[],corn=[],beans=[],threads=[],noriSpeck=[];
for(let i=0;i<26;i++){const a=rnd()*TAU,d=Math.sqrt(rnd())*.36;
  scallions.push({u:Math.cos(a)*d*1.1+.02,v:Math.sin(a)*d+.1,r:rr(7.5,11.5),q:rr(.5,.85),rot:rr(-.6,.6),ph:rnd()*TAU,g:rr(0,1)})}
for(let i=0;i<46;i++){const a=rnd()*TAU,d=Math.sqrt(rnd())*.78;
  sesame.push({u:Math.cos(a)*d,v:Math.sin(a)*d*.9+.08,rot:rnd()*PI,dark:rnd()<.3,ph:rnd()*TAU})}
for(let i=0;i<26;i++){const a=rnd()*TAU,d=Math.sqrt(rnd());
  corn.push({x:Math.cos(a)*d*46,y:Math.sin(a)*d*17-(1-d)*7,rot:rr(-.7,.7),s:rr(.85,1.15)})}
corn.sort((a,b)=>a.y-b.y);
[[.1,.6],[.24,.66],[.02,.74],[.34,.56],[.17,.78],[-.5,.62],[.66,-.02]].forEach((p,i)=>beans.push({u:p[0],v:p[1],rot:rr(-.9,.9),ph:i*1.3}));
for(let i=0;i<16;i++){const a=rnd()*TAU;
  threads.push({x0:rr(-20,20),y0:rr(-8,8),a,len:rr(22,44),c:rr(-22,22),ph:rnd()*TAU})}
for(let i=0;i<70;i++)noriSpeck.push([rnd(),rnd(),rr(.6,1.8),rr(.06,.2)]);
const bob=(u,v,ph,t)=>Math.sin(t*.9+ph)*1.1+rippleAt(u,v,t)*7;

/* ---------- toppings: drawing ---------- */
function shade(x,y,rx,ry,al){
  ctx.fillStyle='rgba(58,20,0,'+al*.5+')';
  ctx.beginPath();ctx.ellipse(x,y,rx*1.15,ry*1.2,0,0,TAU);ctx.fill();
  ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,TAU);ctx.fill();
}
function drawNoriSheet(x,y,w,h,tilt,t,ph){
  const sx=Math.sin(t*.55+ph)*1.6;
  ctx.save();ctx.translate(x,y);ctx.rotate(tilt);
  const p=new Path2D();
  p.moveTo(-w/2,4);p.lineTo(-w/2-3+sx,-h);p.quadraticCurveTo(sx,-h-4,w/2-3+sx,-h+3);p.lineTo(w/2,0);p.quadraticCurveTo(0,10,-w/2,4);p.closePath();
  let g=ctx.createLinearGradient(0,-h,0,6);
  g.addColorStop(0,'#223523');g.addColorStop(.5,'#132015');g.addColorStop(.86,'#0a120b');g.addColorStop(1,'#050805');
  ctx.fillStyle=g;ctx.fill(p);
  ctx.save();ctx.clip(p);
  for(const s of noriSpeck){ctx.fillStyle='rgba(140,186,128,'+s[3]+')';ctx.fillRect(-w/2+s[0]*w,-h+s[1]*h,s[2]*1.6,s[2])}
  g=ctx.createLinearGradient(-w/2,-h,w/2,0);
  const k=clamp(.5+LX*.35,.15,.85);
  g.addColorStop(0,'rgba(150,200,160,0)');g.addColorStop(k,'rgba(160,210,170,.16)');g.addColorStop(1,'rgba(150,200,160,0)');
  ctx.fillStyle=g;ctx.fillRect(-w,-h-10,2*w,h+30);
  ctx.restore();
  ctx.lineWidth=1;ctx.strokeStyle='rgba(170,214,160,.3)';ctx.stroke(p);
  ctx.restore();
}
function drawNori(x,y,t){
  shade(x+10,y+4,62,12,.5);
  drawNoriSheet(x+34,y-6,96,150,.2,t,1.7);
  drawNoriSheet(x-8,y,100,158,.05,t,0);
}
